type TransactionType = "Credit sale" | "Payment received" | "Return";
type Transaction = {
  id: string;
  date: string;
  type: TransactionType;
  detail: string;
  total: number;
  paid: number;
  due: number;
  method?: string;
  createdAt?: number;
};
type Patient = {
  id: string;
  name: string;
  phone: string;
  area: string;
  category: string;
  balance: number;
  visits: number;
  lastVisit: string;
  initials: string;
  purchases: number;
  paid: number;
  tone: string;
  transactions: Transaction[];
};
type LedgerItem = Transaction & { patient: string; patientId: string };

type LedgerKind = "credit" | "payment" | "return";
const tx = (id: string, date: string, type: TransactionType, detail: string, total: number, paid: number, due: number, method?: string): Transaction => ({ id, date, type, detail, total, paid, due, method });
